package com.acme.billing;

import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

@Service
public class InvoiceService {

    private final InvoiceRepository invoiceRepository;

    public InvoiceService(InvoiceRepository invoiceRepository) {
        this.invoiceRepository = invoiceRepository;
    }

    /**
     * Cancels an invoice on behalf of a customer. The customer must own the invoice
     * and it must still be unpaid.
     *
     * An invoice owned by someone else is reported as not found, so callers cannot
     * probe which invoice ids exist.
     */
    @Transactional
    public InvoiceDtos.CancelledInvoice cancel(long invoiceId, long customerId) {
        Invoice invoice = invoiceRepository.findById(invoiceId)
                .filter(found -> found.customerId() == customerId)
                .orElseThrow(() -> new InvoiceNotFoundException(invoiceId));

        if (invoice.status() != InvoiceStatus.UNPAID) {
            throw new InvoiceNotCancellableException(invoiceId, invoice.status());
        }

        invoice.markCancelled();
        return new InvoiceDtos.CancelledInvoice(invoiceId, String.valueOf(invoice.status()));
    }
}
